"""The run manifest: the recipe, content-addressed.

Decision D5 of ``docs/database/phase7_charter.md`` dropped the 100M-deal tier in
favour of making the *recipe* a first-class artifact, because the corpus is a
cache of a pure function: every shard must be regenerable byte-for-byte from
``(root seed, stream range, code identity)``, on any host, with no reference to
the original run's output.  This module is that recipe.

Two properties earn it the name.

**It is self-contained.** Everything that can affect a generated byte is a
field: the root seed, the stratum mixture and its parameters, the seat policy
identities, the score and dealer schedules, the card encoding, the record
layout, and a SHA-256 per source file that participates in play.  ``run_id`` is
the digest of that object, so two manifests that would generate different bytes
cannot share an id.

**Code drift fails rather than being absorbed.**
:func:`RunManifest.verify_sources` recomputes the pinned digests and raises
``CorpusProvenanceError`` on any change, instead of quietly producing
differently-generated shards under the same ``run_id``.  That is the discipline
``docs/nolo/tasks/source_manifest.json`` and ``test_input_provenance`` already
apply to the NOLO evidence packet.

Wall-clock time, host names, output paths and worker counts are deliberately
**not** fields.  They cannot change a generated byte, so including them would
let an irrelevant difference mint a new identity.  They belong in the shard
catalogue, which records what happened rather than what was asked for.
"""

from __future__ import annotations

from dataclasses import dataclass, field
import hashlib
import json
from pathlib import Path

from .errors import CorpusConfigurationError, CorpusProvenanceError
from .packing import CARD_ENCODING, HAND_ORDER_ID, PACKING_SCHEMA_VERSION
from .records import DEAL_ROW_BYTES, MATCH_ROW_BYTES, RECORDS_SCHEMA_VERSION
from .seeds import SEED_SCHEMA_VERSION


MANIFEST_SCHEMA_VERSION = "tuppi.corpus.run_manifest.v1"

#: Every package whose source can change a generated byte. ``tuppi_corpus``
#: itself is included: the stratum mixture and the branch mechanics live here.
PINNED_PACKAGES: tuple[str, ...] = (
    "tuppi_rules",
    "tuppi_engine",
    "tuppi_agents",
    "tuppi_corpus",
)

#: ``tuppi_match.streams`` supplies the deal streams. The rest of that package
#: is evaluation machinery a generation run never reaches.
PINNED_MODULES: tuple[str, ...] = ("tuppi_match/streams.py",)


def source_root() -> Path:
    """The ``src`` directory the running code was imported from."""

    import tuppi_rules

    return Path(tuppi_rules.__file__).resolve().parents[1]


def pin_sources(root: Path | None = None) -> dict[str, str]:
    """A SHA-256 per source file that can affect play, keyed by relative path."""

    base = source_root() if root is None else Path(root)
    digests: dict[str, str] = {}
    candidates: list[Path] = []
    for package in PINNED_PACKAGES:
        candidates.extend(sorted((base / package).glob("*.py")))
    for module in PINNED_MODULES:
        candidates.append(base / module)
    for path in candidates:
        if not path.is_file():
            raise CorpusConfigurationError(f"pinned source is missing: {path}")
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        digests[str(path.relative_to(base))] = f"sha256:{digest}"
    if not digests:
        raise CorpusConfigurationError("no sources were pinned")
    return digests


def _canonical(payload: object) -> str:
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def content_digest(payload: object) -> str:
    return f"sha256:{hashlib.sha256(_canonical(payload).encode('utf-8')).hexdigest()}"


@dataclass(frozen=True, slots=True)
class RunManifest:
    """The complete, content-addressed description of one generation run."""

    root_seed: str
    stream_start: int
    stream_stop: int
    shard_streams: int
    mixture: tuple[tuple[str, int], ...]
    policy_sets: tuple[tuple[str, str, str, str], ...]
    heldout_policy_sets: int
    score_schedule: tuple[tuple[int, int], ...]
    stratified_score_schedule: tuple[tuple[int, int], ...]
    reference_agent_id: str
    reference_profile_key: str
    epsilon_branch_probability_numerator: int
    epsilon_branch_probability_denominator: int
    softening_top_k: int
    softening_probability_numerator: int
    softening_probability_denominator: int
    match_deal_cap: int
    revalidation_period: int
    exact_label_max_tricks: int
    split_boundaries: tuple[int, int]
    sources: dict[str, str] = field(default_factory=dict)
    ruleset_id: str = "project_target_v1"
    schema_version: str = MANIFEST_SCHEMA_VERSION

    def __post_init__(self) -> None:
        if self.schema_version != MANIFEST_SCHEMA_VERSION:
            raise CorpusConfigurationError("unsupported run manifest schema")
        if not isinstance(self.root_seed, str) or not self.root_seed:
            raise CorpusConfigurationError("root_seed must be a nonempty string")
        if not 0 <= self.stream_start < self.stream_stop:
            raise CorpusConfigurationError("stream range must satisfy 0 <= start < stop")
        if self.shard_streams <= 0:
            raise CorpusConfigurationError("shard_streams must be positive")
        if not self.mixture or any(weight <= 0 for _, weight in self.mixture):
            raise CorpusConfigurationError("every stratum weight must be positive")
        if len({name for name, _ in self.mixture}) != len(self.mixture):
            raise CorpusConfigurationError("stratum names must be unique")
        if not self.policy_sets or any(len(row) != 4 for row in self.policy_sets):
            raise CorpusConfigurationError("each policy set names four seats")
        if len(self.policy_sets) > 0xFF or len(self.mixture) > 0xFF:
            raise CorpusConfigurationError("policy sets and strata must fit in a byte")
        if not 0 <= self.heldout_policy_sets < len(self.policy_sets):
            raise CorpusConfigurationError(
                "heldout_policy_sets must reserve fewer sets than exist"
            )
        if not self.score_schedule or not self.stratified_score_schedule:
            raise CorpusConfigurationError("both score schedules must be nonempty")
        for label, schedule in (
            ("score_schedule", self.score_schedule),
            ("stratified_score_schedule", self.stratified_score_schedule),
        ):
            if any(len(pair) != 2 or min(pair) < 0 for pair in schedule):
                raise CorpusConfigurationError(f"{label} holds nonnegative pairs")
            # Reject an unconstructible score here rather than 100 seconds into
            # a run: only one team may hold a positive rising score.
            from tuppi_rules import MatchScore
            from tuppi_rules.errors import RulesError

            for pair in schedule:
                try:
                    MatchScore(*pair)
                except RulesError as exc:
                    raise CorpusConfigurationError(
                        f"{label} entry {tuple(pair)} is not a legal match score: {exc}"
                    ) from exc
        if self.match_deal_cap <= 0 or self.revalidation_period <= 0:
            raise CorpusConfigurationError("deal cap and revalidation period are positive")
        if not 0 <= self.exact_label_max_tricks <= 6:
            raise CorpusConfigurationError("exact_label_max_tricks must be 0..6")
        if self.softening_top_k < 1:
            raise CorpusConfigurationError("softening_top_k must be at least one")
        for numerator, denominator, label in (
            (
                self.epsilon_branch_probability_numerator,
                self.epsilon_branch_probability_denominator,
                "epsilon",
            ),
            (
                self.softening_probability_numerator,
                self.softening_probability_denominator,
                "softening",
            ),
        ):
            if denominator <= 0 or not 0 <= numerator <= denominator:
                raise CorpusConfigurationError(f"{label} probability is out of range")
        low, high = self.split_boundaries
        if not 0 < low < high < 1000:
            raise CorpusConfigurationError(
                "split boundaries must satisfy 0 < train < validation < 1000"
            )

    # ------------------------------------------------------------- identity

    def identity_data(self) -> dict[str, object]:
        """Everything that can change a generated byte, and nothing else."""

        return {
            "card_encoding": CARD_ENCODING,
            "deal_row_bytes": DEAL_ROW_BYTES,
            "epsilon_branch_probability": [
                self.epsilon_branch_probability_numerator,
                self.epsilon_branch_probability_denominator,
            ],
            "exact_label_max_tricks": self.exact_label_max_tricks,
            "hand_order": HAND_ORDER_ID,
            "heldout_policy_sets": self.heldout_policy_sets,
            "match_deal_cap": self.match_deal_cap,
            "match_row_bytes": MATCH_ROW_BYTES,
            "mixture": [[name, weight] for name, weight in self.mixture],
            "packing_schema": PACKING_SCHEMA_VERSION,
            "policy_sets": [list(row) for row in self.policy_sets],
            "records_schema": RECORDS_SCHEMA_VERSION,
            "reference_agent_id": self.reference_agent_id,
            "reference_profile_key": self.reference_profile_key,
            "revalidation_period": self.revalidation_period,
            "root_seed": self.root_seed,
            "ruleset_id": self.ruleset_id,
            "schema_version": self.schema_version,
            "score_schedule": [list(pair) for pair in self.score_schedule],
            "seed_schema": SEED_SCHEMA_VERSION,
            "shard_streams": self.shard_streams,
            "softening": [
                self.softening_top_k,
                self.softening_probability_numerator,
                self.softening_probability_denominator,
            ],
            "sources": dict(sorted(self.sources.items())),
            "split_boundaries": list(self.split_boundaries),
            "stratified_score_schedule": [
                list(pair) for pair in self.stratified_score_schedule
            ],
            "stream_start": self.stream_start,
            "stream_stop": self.stream_stop,
        }

    @property
    def run_id(self) -> str:
        """``run:sha256:...``, matching every other identity in the repository."""

        return f"run:{content_digest(self.identity_data())}"

    def to_data(self) -> dict[str, object]:
        return {"identity": self.identity_data(), "run_id": self.run_id}

    def write(self, path: Path) -> str:
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_text(_canonical(self.to_data()) + "\n", encoding="utf-8")
        return self.run_id

    # ------------------------------------------------------------ provenance

    def verify_sources(self, root: Path | None = None) -> None:
        """Raise if any pinned source has changed since the manifest was built."""

        if not self.sources:
            raise CorpusProvenanceError("manifest pins no sources; refusing to trust it")
        current = pin_sources(root)
        missing = sorted(set(self.sources) - set(current))
        added = sorted(set(current) - set(self.sources))
        changed = sorted(
            name
            for name in set(self.sources) & set(current)
            if self.sources[name] != current[name]
        )
        if missing or added or changed:
            raise CorpusProvenanceError(
                "pinned sources have drifted; regeneration would not reproduce this "
                f"run. missing={missing} added={added} changed={changed}"
            )

    # ------------------------------------------------------------- geometry

    def shard_bounds(self) -> tuple[tuple[int, int], ...]:
        """The stream range of every shard, in order.  A shard is the unit of work."""

        bounds: list[tuple[int, int]] = []
        start = self.stream_start
        while start < self.stream_stop:
            stop = min(start + self.shard_streams, self.stream_stop)
            bounds.append((start, stop))
            start = stop
        return tuple(bounds)


def load_manifest(path: Path) -> RunManifest:
    """Read a manifest and check that its recorded ``run_id`` still rebuilds."""

    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    if type(payload) is not dict or "identity" not in payload:
        raise CorpusConfigurationError("manifest file is malformed")
    identity = payload["identity"]
    manifest = RunManifest(
        root_seed=identity["root_seed"],
        stream_start=identity["stream_start"],
        stream_stop=identity["stream_stop"],
        shard_streams=identity["shard_streams"],
        mixture=tuple((name, weight) for name, weight in identity["mixture"]),
        policy_sets=tuple(tuple(row) for row in identity["policy_sets"]),
        heldout_policy_sets=identity["heldout_policy_sets"],
        score_schedule=tuple(tuple(pair) for pair in identity["score_schedule"]),
        stratified_score_schedule=tuple(
            tuple(pair) for pair in identity["stratified_score_schedule"]
        ),
        reference_agent_id=identity["reference_agent_id"],
        reference_profile_key=identity["reference_profile_key"],
        epsilon_branch_probability_numerator=identity["epsilon_branch_probability"][0],
        epsilon_branch_probability_denominator=identity["epsilon_branch_probability"][1],
        softening_top_k=identity["softening"][0],
        softening_probability_numerator=identity["softening"][1],
        softening_probability_denominator=identity["softening"][2],
        match_deal_cap=identity["match_deal_cap"],
        revalidation_period=identity["revalidation_period"],
        exact_label_max_tricks=identity["exact_label_max_tricks"],
        split_boundaries=tuple(identity["split_boundaries"]),
        sources=dict(identity["sources"]),
        ruleset_id=identity["ruleset_id"],
    )
    if manifest.run_id != payload["run_id"]:
        raise CorpusProvenanceError(
            "manifest run_id does not rebuild from its own content"
        )
    if identity.get("hand_order") != HAND_ORDER_ID:
        raise CorpusProvenanceError("manifest was written under a different hand order")
    if identity["card_encoding"] != CARD_ENCODING:
        raise CorpusProvenanceError("manifest was written under a different card encoding")
    if (
        identity["deal_row_bytes"] != DEAL_ROW_BYTES
        or identity["match_row_bytes"] != MATCH_ROW_BYTES
    ):
        raise CorpusProvenanceError("manifest was written under a different row layout")
    return manifest


__all__ = [
    "MANIFEST_SCHEMA_VERSION",
    "PINNED_MODULES",
    "PINNED_PACKAGES",
    "RunManifest",
    "content_digest",
    "load_manifest",
    "pin_sources",
    "source_root",
]
